const headerCta = document.querySelector('.nav-cta');
const mobileCta = document.querySelector('.mobile-cta');
const makeConsultButton = (className, text) => `<button class="${className}" type="button">${text}</button>`;
if (headerCta) headerCta.outerHTML = makeConsultButton('nav-cta consult-trigger', 'Đăng ký tư vấn');
if (mobileCta) mobileCta.outerHTML = makeConsultButton('mobile-cta consult-trigger', 'Đăng ký tư vấn');
document.body.insertAdjacentHTML('beforeend', `<div class="consult-modal" id="consult-modal" role="dialog" aria-modal="true" aria-labelledby="consult-modal-title" aria-hidden="true"><div class="consult-modal-backdrop" data-close-consult></div><section class="consult-modal-panel" role="document"><button class="consult-modal-close" type="button" aria-label="Đóng biểu mẫu" data-close-consult>×</button><div class="consult-modal-kicker">UKEA • TƯ VẤN BÀI THI OTE</div><h2 id="consult-modal-title">Đăng ký nhận tư vấn</h2><p>Để lại thông tin, đội ngũ UKEA sẽ hỗ trợ bạn chọn bài thi phù hợp. Hotline: <a href="tel:0989999999">0989 999 999</a>.</p><form id="consult-modal-form" novalidate><label>Họ và tên<input name="fullName" autocomplete="name" required></label><label>Số điện thoại<input name="phone" type="tel" autocomplete="tel" required></label><label>Email <span>(không bắt buộc)</span><input name="email" type="email" autocomplete="email"></label><label>Nhu cầu tư vấn<select name="interest"><option>Oxford Test of English</option><option>OTE Advanced</option><option>Địa điểm và lịch thi</option><option>Khác</option></select></label><label class="consult-consent"><input name="consent" type="checkbox" required><span>Tôi đồng ý để UKEA liên hệ tư vấn về bài thi OTE.</span></label><button class="consult-submit" type="submit">Gửi đăng ký</button><p class="consult-form-message" aria-live="polite"></p></form></section></div>`);
const consultModal = document.querySelector('#consult-modal');
const consultPanel = consultModal.querySelector('.consult-modal-panel');
const consultForm = consultModal.querySelector('form');
let opener;
const openConsult = event => { opener = event.currentTarget; consultModal.classList.add('is-open'); consultModal.setAttribute('aria-hidden', 'false'); document.body.classList.add('consult-locked'); setTimeout(() => consultModal.querySelector('input').focus(), 20) };
const closeConsult = () => { consultModal.classList.remove('is-open'); consultModal.setAttribute('aria-hidden', 'true'); document.body.classList.remove('consult-locked'); opener?.focus() };
document.querySelectorAll('.consult-trigger').forEach(button => button.addEventListener('click', openConsult));
consultModal.querySelectorAll('[data-close-consult]').forEach(button => button.addEventListener('click', closeConsult));
consultModal.addEventListener('keydown', event => { if (event.key === 'Escape') { event.stopPropagation(); closeConsult() } if (event.key === 'Tab') { const focusable = [...consultPanel.querySelectorAll('button,input,select')].filter(element => !element.disabled); const first = focusable[0], last = focusable.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() } } });
consultForm.addEventListener('submit', event => { event.preventDefault(); const message = consultForm.querySelector('.consult-form-message'); if (!consultForm.checkValidity()) { consultForm.reportValidity(); return } message.textContent = 'Cảm ơn bạn. Thông tin sẽ được lưu ngay khi website kết nối Supabase.'; consultForm.reset() });
